["40280"]={["Title"]="布蕾达的训练", ["Objectives"]="在宠物战斗中击败布蕾达·柔鬃。", ["Description"]="", ["Progress"]="", ["Completion"]="", ["Translator"]=""},
["40282"]={["Title"]="小动物偷猎者", ["Objectives"]="在宠物战斗中击败格里克斯·微泡。", ["Description"]="", ["Progress"]="", ["Completion"]="", ["Translator"]=""},
["40297"]={["Title"]="莉安娜·悲夜", ["Objectives"]="摧毁灵魂收割器。", ["Description"]="", ["Progress"]="", ["Completion"]="", ["Translator"]=""},
