["45751"]={["Title"]="斯卡德诺克斯的核铸印记", ["Objectives"]="", ["Description"]="高阶深渊议会的印记是用从其持有者的元素中萃取出的精华制作的。这个印记是在烈火中铸造的。", ["Progress"]="", ["Completion"]="", ["Translator"]=""},
["45752"]={["Title"]="维拉希斯的微光印记", ["Objectives"]="把维拉希斯的微光印记带给希利苏斯的督军格尔库克。", ["Description"]="高阶深渊议会的印记是用从其持有者的元素中萃取出的精华制作的。这个印记是用刺骨的狂风雕刻而成。", ["Progress"]="", ["Completion"]="", ["Translator"]=""},
["45753"]={["Title"]="卡苏姆的钻石印记", ["Objectives"]="", ["Description"]="高阶深渊议会的印记是用从其持有者的元素中萃取出的精华制作的。这个印记是用石头雕刻而成，然后熔进了一颗无瑕的钻石。", ["Progress"]="", ["Completion"]="", ["Translator"]=""},
