["50860"]={["Title"]="惹是生非", ["Objectives"]="在蛮荒之地寻找库亚冯并营救它。", ["Description"]="库亚冯的个头已经很大了。也许它觉得自己已经和丛林里的野兽一样强壮了。NEW_LINENEW_LINE它很快就会发现事实并非如此。趁它还没有因为鲁莽而丢掉性命之前，把它找回来。NEW_LINENEW_LINE我听到北面发出了一阵骚动。先从那里开始。", ["Progress"]="", ["Completion"]="", ["Translator"]=""},
["50861"]={["Title"]="永恒者托拉斯科", ["Objectives"]="", ["Description"]="", ["Progress"]="", ["Completion"]="", ["Translator"]=""},
["50862"]={["Title"]="血囊蛛", ["Objectives"]="", ["Description"]="", ["Progress"]="", ["Completion"]="", ["Translator"]=""},
["50863"]={["Title"]="索洛塔尔的化身", ["Objectives"]="", ["Description"]="", ["Progress"]="", ["Completion"]="", ["Translator"]=""},
["50864"]={["Title"]="阿塔祖尔之苟塔卡", ["Objectives"]="", ["Description"]="", ["Progress"]="", ["Completion"]="", ["Translator"]=""},
["50866"]={["Title"]="查羽斯", ["Objectives"]="", ["Description"]="", ["Progress"]="", ["Completion"]="", ["Translator"]=""},
["50867"]={["Title"]="坦巴诺", ["Objectives"]="", ["Description"]="", ["Progress"]="", ["Completion"]="", ["Translator"]=""},
