["61265"]={["Title"]="图纸：敏锐护符", ["Objectives"]="将图纸：敏锐护符带给戴克泰丽丝。", ["Description"]="<你发现了一张护符图纸，它也许能让你的灵魂羁绊在晋升之路中身手矫健。NEW_LINENEW_LINE戴克泰丽丝应该可以帮你制造这件护符。>", ["Progress"]="", ["Completion"]="", ["Translator"]=""},
["61269"]={["Title"]="图纸：毅力护符", ["Objectives"]="将图纸：毅力护符带给戴克泰丽丝。", ["Description"]="<你发现了一张护符图纸，能鼓励你的灵魂羁绊在晋升之路上坚持奋战。NEW_LINENEW_LINE戴克泰丽丝应该能帮助你制作这个护符。>", ["Progress"]="", ["Completion"]="", ["Translator"]=""},
["61272"]={["Title"]="图纸：分歧护符", ["Objectives"]="将图纸：分歧护符带给戴克泰丽丝。", ["Description"]="<你发现了一张护符图纸，它也许能让你的灵魂羁绊在晋升之路中击溃强敌。NEW_LINENEW_LINE戴克泰丽丝应该可以帮你制造这件护符。>", ["Progress"]="", ["Completion"]="", ["Translator"]=""},
["61303"]={["Title"]="火星如雨", ["Objectives"]="", ["Description"]="", ["Progress"]="", ["Completion"]="", ["Translator"]=""},
["61304"]={["Title"]="图纸：格里恩铁匠修理包", ["Objectives"]="将图纸：格里恩铁匠修理包带给戴克泰丽丝。", ["Description"]="<你发现了能在冒险途中修复护甲的物品图纸。NEW_LINENEW_LINE戴克泰丽丝应该能帮助你制作这个物品。>", ["Progress"]="", ["Completion"]="", ["Translator"]=""},
