["62429"]={["Title"]="狮子之魂", ["Objectives"]="把狮子之魂带给森林之心中的曼恩女士。", ["Description"]="<狮子之魂强大而勇猛。你将掌握狮子形态。>", ["Progress"]="", ["Completion"]="", ["Translator"]=""},
["62430"]={["Title"]="驼鹿之魂", ["Objectives"]="把驼鹿之魂带给森林之心中的曼恩女士。", ["Description"]="<驼鹿之魂强韧而仁爱。你将掌握驼鹿形态。>", ["Progress"]="", ["Completion"]="", ["Translator"]=""},
["62431"]={["Title"]="暗影追猎者之魂", ["Objectives"]="把暗影追猎者之魂带给森林之心中的曼恩女士。", ["Description"]="<暗影追猎者之魂狡黠而谨慎。你将掌握暗影追猎者形态。>", ["Progress"]="", ["Completion"]="", ["Translator"]=""},
["62432"]={["Title"]="鹰头猫之魂", ["Objectives"]="把鹰头猫之魂带给森林之心中的曼恩女士。", ["Description"]="<鹰头猫之魂外表奇特，又酷爱恶作剧，是众多部件以顽皮的平衡组合运作的一种野兽，总是不断寻找着新的挑战。你将掌握鹰头猫形态。>", ["Progress"]="", ["Completion"]="", ["Translator"]=""},
["62433"]={["Title"]="迅猛龙之魂", ["Objectives"]="把迅猛龙之魂带给森林之心中的曼恩女士。", ["Description"]="<迅猛龙之魂忠诚而凶悍。你将掌握迅猛龙形态。>", ["Progress"]="", ["Completion"]="", ["Translator"]=""},
