["62435"]={["Title"]="牡鹿之魂", ["Objectives"]="把牡鹿之魂带给森林之心中的曼恩女士。", ["Description"]="<牡鹿之魂高贵而威猛。你将掌握牡鹿形态。>", ["Progress"]="", ["Completion"]="", ["Translator"]=""},
["62436"]={["Title"]="尖啸者之魂", ["Objectives"]="把尖啸者之魂带给森林之心中的曼恩女士。", ["Description"]="<尖啸者之魂迅捷而凶暴。你将掌握帷幕尖啸者形态。>", ["Progress"]="", ["Completion"]="", ["Translator"]=""},
["62437"]={["Title"]="老虎之魂", ["Objectives"]="把老虎之魂带给森林之心中的曼恩女士。", ["Description"]="<老虎之魂高傲而强大。你将掌握老虎形态。>", ["Progress"]="", ["Completion"]="", ["Translator"]=""},
