["64988"]={["Title"]="蛇之魂", ["Objectives"]="把蛇之魂带给森林之心中的丘法。", ["Description"]="<蛇之魂耐心而警惕。你将掌握蛇形态。>", ["Progress"]="", ["Completion"]="", ["Translator"]=""},
["64989"]={["Title"]="箭猪之魂", ["Objectives"]="把箭猪之魂带给森林之心中的丘法。", ["Description"]="<箭猪之魂谨慎而害羞。你将掌握箭猪形态。>", ["Progress"]="", ["Completion"]="", ["Translator"]=""},
["64990"]={["Title"]="蟋蟀之魂", ["Objectives"]="把蟋蟀之魂带给森林之心中的丘法。", ["Description"]="<蟋蟀之魂非常幸运。你将掌握蟋蟀形态。>", ["Progress"]="", ["Completion"]="", ["Translator"]=""},
["64992"]={["Title"]="草原土拨鼠之魂", ["Objectives"]="把草原土拨鼠之魂带给森林之心中的丘法。", ["Description"]="<草原土拨鼠之魂十分警醒。你将掌握草原土拨鼠形态。>", ["Progress"]="", ["Completion"]="", ["Translator"]=""},
["64993"]={["Title"]="巨蜥幼体之魂", ["Objectives"]="把巨蜥幼体之魂带给森林之心中的丘法。", ["Description"]="<巨蜥幼体之魂坚韧而凶猛。你将掌握巨蜥幼体形态。>", ["Progress"]="", ["Completion"]="", ["Translator"]=""},
["64994"]={["Title"]="青蛙之魂", ["Objectives"]="把青蛙之魂带给森林之心中的丘法。", ["Description"]="<青蛙之魂充满欢乐，总爱唱歌。你将掌握青蛙形态。>", ["Progress"]="", ["Completion"]="", ["Translator"]=""},
["64995"]={["Title"]="细颚龙之魂", ["Objectives"]="把细颚龙之魂带给森林之心中的丘法。", ["Description"]="<细颚龙之魂喜欢恶作剧。你将掌握细颚龙形态。>", ["Progress"]="", ["Completion"]="", ["Translator"]=""},
