["72116"]={["Title"]="炫目的里斯克隆", ["Objectives"]="", ["Description"]="", ["Progress"]="", ["Completion"]="", ["Translator"]=""},
["72117"]={["Title"]="文化交流", ["Objectives"]="", ["Description"]="", ["Progress"]="", ["Completion"]="", ["Translator"]=""},
